import type { ReactNode } from "react";

export interface Post {
  slug: string;
  title: string;
  excerpt: string;
  body: ReactNode;
  publishedAt: string;
}

export const POSTS: Post[] = [
  {
    slug: "hello-world",
    title: "Hello, world",
    excerpt: "The first post on this brand-new blog.",
    body: "Welcome. This is the first post on this brand-new blog.",
    publishedAt: "2026-01-12",
  },
  {
    slug: "on-writing",
    title: "On writing",
    excerpt: "A short note on why writing is worth the time.",
    body: "Writing is thinking made visible.",
    publishedAt: "2026-02-02",
  },
];

import { createFileRoute, Link } from "@tanstack/react-router";
import { POSTS } from "@/lib/posts";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

export const Route = createFileRoute("/")({
  component: HomePage,
  head: () => ({
    meta: [
      { title: "My blog" },
      { name: "description", content: "Notes, essays, and short reads." },
    ],
  }),
});

function HomePage() {
  return (
    <main className="mx-auto max-w-2xl p-6">
      <header className="mb-10">
        <h1 className="text-4xl font-bold tracking-tight">My blog</h1>
        <p className="mt-2 text-muted-foreground">
          Notes, essays, and short reads.
        </p>
      </header>
      <ul className="space-y-4">
        {POSTS.map((p) => (
          <li key={p.slug}>
            <Link
              to="/posts/$slug"
              params={{ slug: p.slug }}
              className="block"
            >
              <Card className="transition hover:bg-accent">
                <CardHeader>
                  <CardTitle>{p.title}</CardTitle>
                </CardHeader>
                <CardContent className="text-sm text-muted-foreground">
                  {p.excerpt}
                </CardContent>
              </Card>
            </Link>
          </li>
        ))}
      </ul>
    </main>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { POSTS } from "@/lib/posts";

export const Route = createFileRoute("/posts/")({
  component: PostsIndex,
  head: () => ({
    meta: [
      { title: "All posts" },
      { name: "description", content: "Every post on the blog." },
    ],
  }),
});

function PostsIndex() {
  return (
    <main className="mx-auto max-w-2xl p-6">
      <h1 className="mb-6 text-3xl font-bold tracking-tight">All posts</h1>
      <ul className="space-y-3">
        {POSTS.map((p) => (
          <li key={p.slug}>
            <Link
              to="/posts/$slug"
              params={{ slug: p.slug }}
              className="text-primary underline-offset-4 hover:underline"
            >
              {p.title}
            </Link>
            <span className="ml-2 text-xs text-muted-foreground">
              {p.publishedAt}
            </span>
          </li>
        ))}
      </ul>
    </main>
  );
}

import { createFileRoute, Link, notFound } from "@tanstack/react-router";
import { POSTS } from "@/lib/posts";

export const Route = createFileRoute("/posts/$slug")({
  component: PostDetail,
  loader: ({ params }) => {
    const post = POSTS.find((p) => p.slug === params.slug);
    if (!post) throw notFound();
    return { post };
  },
  head: ({ loaderData }) => ({
    meta: [
      { title: loaderData?.post.title ?? "Post" },
      {
        name: "description",
        content: loaderData?.post.excerpt ?? "A blog post.",
      },
    ],
  }),
  notFoundComponent: () => (
    <main className="mx-auto max-w-2xl p-6">
      <h1 className="text-3xl font-bold">Post not found</h1>
      <Link to="/" className="text-primary hover:underline">
        Back home
      </Link>
    </main>
  ),
});

function PostDetail() {
  const { post } = Route.useLoaderData();
  return (
    <main className="mx-auto max-w-2xl p-6">
      <Link
        to="/"
        className="text-sm text-muted-foreground hover:text-foreground"
      >
        ← Back
      </Link>
      <article className="mt-4 prose prose-neutral dark:prose-invert">
        <h1>{post.title}</h1>
        <p className="text-sm text-muted-foreground">{post.publishedAt}</p>
        <div>{post.body}</div>
      </article>
    </main>
  );
}
